    fn now(&self) -> Instant {
        match self {
            Self::System => Instant::now(),
            Self::Injected(clock) => clock.now(),
        }
    }
    async fn sleep_until(&self, deadline: Instant) {
        match self {
            Self::System => tokio::time::sleep_until(deadline).await,
            Self::Injected(clock) => clock.sleep_until(deadline).await,
        }
    }
